scriptdefs
= RustboroCity_Gym_EventScript_Marc
trainerbattle_single TRAINER_MARC RustboroCity_Gym_Text_MarcIntro RustboroCity_Gym_Text_MarcDefeat
msgbox	Das muss ich unserer LEADER lassen.Es brauchte Verstand und Gespür, sich in ihrem jungen Alter für den GESTEIN-Typ zu entscheiden.
end
= RustboroCity_Gym_EventScript_GymGuide
lock
faceplayer
goto_if_set FLAG_DEFEATED_RUSTBORO_GYM RustboroCity_Gym_EventScript_GymGuidePostVictory
msgbox	Yo, wie läuft's?Hör zu, mein Freund! Möchtest du CHAMPION werden?Ich bin kein TRAINER, ich nicht, aber ich kann dir sicher gewinnbringende Tipps geben.Also gut, abgemacht! Wir peilen die POKéMON CHAMPIONSHIP zusammen an!Es ist deine Aufgabe als TRAINER, GYM BADGES zu sammeln, richtig?Aber GYM LEADER sind kein Zuckerschlecken!Und da komme ich ins Spiel! Ich bin hier, um dir Expertentipps zu geben!ROXANNE, die GYM LEADER, setzt auf GESTEIN-POKéMON.Der GESTEIN-Typ ist sehr widerstandsfähig, aber er kann WASSER- und PFLANZEN-Attacken nicht ab.Komm danach nochmal zu mir, wenn du den GYM LEADER besiegt hast.Na dann, viel Erfolg!
release
end
= RustboroCity_Gym_EventScript_GymGuidePostVictory
msgbox	Whoa! Was für ein atemberaubender Sieg! Mein Anfeuern muss geholfen haben!Großartig! Schau in deine TRAINER CARD.Das STONE BADGE, das du bekommen hast, sollte dort ordentlich vermerkt sein.Mit anderen Worten…Du hast die erste Stufe auf der Treppe zur CHAMPIONSHIP erklommen!Das muss sich großartig anfühlen!
release
end
= RustboroCity_Gym_EventScript_Tommy
trainerbattle_single TRAINER_TOMMY RustboroCity_Gym_Text_TommyIntro RustboroCity_Gym_Text_TommyDefeat
msgbox	ROXANNE ist um einiges stärker als ich.Du solltest besser auf der Hut sein!
end
= RustboroCity_Gym_EventScript_Josh
trainerbattle_single TRAINER_JOSH RustboroCity_Gym_Text_JoshIntro RustboroCity_Gym_Text_JoshDefeat
msgbox	Du hast noch gar nichts von der erschreckenden Kraft des GESTEIN-Typs gesehen!
end
= RustboroCity_Gym_EventScript_Roxanne
trainerbattle_single TRAINER_ROXANNE_1 RustboroCity_Gym_Text_RoxanneIntro RustboroCity_Gym_Text_RoxanneDefeat RustboroCity_Gym_EventScript_RoxanneDefeated NO_MUSIC
specialvar VAR_RESULT ShouldTryRematchBattle
goto_if_eq VAR_RESULT TRUE RustboroCity_Gym_EventScript_RoxanneRematch
goto_if_unset FLAG_RECEIVED_TM_ROCK_TOMB RustboroCity_Gym_EventScript_GiveRockTomb
msgbox	Weil du so stark bist, solltest du auch andere GYM LEADER herausfordern.Wenn du gegen viele TRAINER kämpfst, lernst du bestimmt eine Menge.
release
end
= RustboroCity_Gym_EventScript_GiveRockTomb
giveitem ITEM_TM_ROCK_TOMB
goto_if_eq VAR_RESULT FALSE Common_EventScript_ShowBagIsFull
setflag FLAG_RECEIVED_TM_ROCK_TOMB
msgbox	Dieses TECHNICAL MACHINE, TM39, enthält ROCK TOMB.Es fügt nicht nur Schaden zu, indem es Steine fallen lässt, sondern senkt auch die SPEED.Wenn du ein TM benutzt, bringt es einem POKéMON die Attacke sofort bei.Denk dran, ein TM lässt sich nur einmal benutzen, überleg also, bevor du es einsetzt.
release
end
= RustboroCity_Gym_EventScript_RoxanneRematch
trainerbattle_rematch_double TRAINER_ROXANNE_1 RustboroCity_Gym_Text_RoxannePreRematch RustboroCity_Gym_Text_RoxanneRematchDefeat RustboroCity_Gym_Text_RoxanneRematchNeedTwoMons
msgbox	ROXANNE: Ich hab noch viel zu lernen, wenn es um POKéMON-Kämpfe geht.Genau dieses Bewusstsein lässt mich das Kämpfen nur noch mehr lieben!
end
= RustboroCity_Gym_EventScript_RoxanneDefeated
msgbox	PLAYER hat das STONE BADGE von ROXANNE erhalten.
waitmessage
call Common_EventScript_PlayGymBadgeFanfare
msgbox	Das STONE BADGE erhöht die ANGRIFFSKRAFT deiner POKéMON.Es ermöglicht ihnen außerdem, die HM-Attacke CUT außerhalb von Kämpfen einzusetzen.Bitte nimm auch das hier mit.
setflag FLAG_DEFEATED_RUSTBORO_GYM
setflag FLAG_BADGE01_GET
setvar VAR_RUSTBORO_CITY_STATE 1
addvar VAR_PETALBURG_GYM_STATE 1
setvar VAR_0x8008 1
call Common_EventScript_SetGymTrainers
call_if_eq VAR_PETALBURG_GYM_STATE 6 Common_EventScript_ReadyPetalburgGymForBattle
goto RustboroCity_Gym_EventScript_GiveRockTomb
end
